//! Committed H.264 vector plus Annex B picture splitting.
//!
//! Vector `tests/vectors/valid_320x240.h264` holds 15 ffmpeg
//! testsrc2 pictures (320x240 constrained baseline, IDR at 0 and
//! 8), generated by:
//! `ffmpeg -f lavfi -i testsrc2=size=320x240:rate=30:duration=0.5
//! -c:v libx264 -profile:v baseline -level 3.1 -pix_fmt yuv420p
//! -g 8 -bf 0 -f h264 valid_320x240.h264`.

use std::path::PathBuf;

/// Committed vector path.
pub(crate) fn vector() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors/valid_320x240.h264")
}

/// Vector bytes grouped into one packet per picture.
pub(crate) fn picture_packets() -> Vec<Vec<u8>> {
    let data = std::fs::read(vector()).expect("vector readable");
    let mut packets = Vec::new();
    let mut current = Vec::new();
    let mut seen_vcl = false;
    for nal in split_nals(&data) {
        let vcl = matches!(nal.first().map(|header| header & 0x1F), Some(1 | 5));
        if vcl && seen_vcl {
            packets.push(std::mem::take(&mut current));
            seen_vcl = false;
        }
        seen_vcl |= vcl;
        current.extend_from_slice(&[0, 0, 0, 1]);
        current.extend_from_slice(nal);
    }
    if !current.is_empty() {
        packets.push(current);
    }
    packets
}

/// NAL units without start codes.
fn split_nals(data: &[u8]) -> Vec<&[u8]> {
    let mut nals = Vec::new();
    let mut start = 0;
    let mut zeros = 0;
    let mut index = 0;
    while index < data.len() {
        if data[index] == 1 && zeros >= 2 {
            let end = index - zeros;
            if end > start {
                nals.push(&data[start..end]);
            }
            start = index + 1;
            zeros = 0;
        } else if data[index] == 0 {
            zeros += 1;
        } else {
            zeros = 0;
        }
        index += 1;
    }
    if start < data.len() {
        nals.push(&data[start..]);
    }
    nals
}
